parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "company": { "type": ["string", "null"], "description": "Requesting company name, only if explicitly written in the text. Null otherwise." },
    "contact_name": { "type": ["string", "null"], "description": "Sender name, only if explicitly written. Null otherwise." },
    "line_items": {
      "type": "array",
      "description": "One entry per requested part. Only parts explicitly mentioned in the text.",
      "items": {
        "type": "object",
        "properties": {
          "part_number": { "type": ["string", "null"], "description": "Exact part number as written. Null if none given." },
          "description": { "type": ["string", "null"], "description": "Part description as written. Null if none given." },
          "quantity": { "type": ["number", "null"], "description": "Quantity explicitly stated for this part. Null if not stated." },
          "unit": { "type": ["string", "null"], "description": "Unit as written (pcs, kg, sets). Null if not stated." },
          "target_price": { "type": ["string", "null"], "description": "Target price ONLY if the text states one for this part. Null if not stated." }
        }
      }
    },
    "need_by_date": { "type": ["string", "null"], "description": "Required delivery date, only if a date appears in the text. Null otherwise." },
    "ship_to_address": { "type": ["string", "null"], "description": "Delivery address, only if one appears in the text. Null otherwise." },
    "packaging_spec": { "type": ["string", "null"], "description": "Packaging requirements, only if stated in the text. Null otherwise." },
    "incoterms": { "type": ["string", "null"], "description": "Incoterms, only if stated. Null otherwise." },
    "special_requirements": { "type": ["string", "null"], "description": "Certs, finishes, inspection requirements explicitly stated. Null otherwise." }
  }
}

parameters.jsCode:
// EDIT: fields required before an RFQ is quotable
const REQUIRED = [
  { key: "line_items", label: "part numbers and quantities" },
  { key: "need_by_date", label: "need-by date" },
  { key: "ship_to_address", label: "ship-to address" },
  { key: "packaging_spec", label: "packaging requirements" },
];

const extracted = $json.output ?? $json;
const meta = $("Normalize Email").item.json;
const isEmpty = (v) => v === null || v === undefined || (typeof v === "string" && v.trim() === "") || (Array.isArray(v) && v.length === 0);

const missing = [];
for (const req of REQUIRED) {
  if (isEmpty(extracted[req.key])) missing.push(req.label);
}
const items = Array.isArray(extracted.line_items) ? extracted.line_items : [];
if (items.length > 0 && items.some((li) => !li.quantity)) missing.push("quantity for every line item");

const itemLines = items.map((li) =>
  "- " + (li.part_number || li.description || "item") + " | qty: " + (li.quantity || "?") + (li.unit ? " " + li.unit : "") + (li.target_price ? " | target: " + li.target_price : "") + " | unit price: ____ | lead time: ____"
).join("\n");

return { json: {
  ...extracted,
  line_items_json: JSON.stringify(items),
  line_items_text: itemLines,
  missing,
  missing_text: missing.map((m) => "- " + m).join("\n"),
  complete: missing.length === 0,
  from_email: meta.from_email,
  subject_line: meta.subject_line,
  thread_id: meta.thread_id,
  received_at: meta.received_at,
} };

